import subprocess, os, glob
print("CWD:", os.getcwd())
hits = []
for root in [os.getcwd(), "/tmp", os.path.expanduser("~"), "/data", "/mnt", "/workspace"]:
    if os.path.isdir(root):
        for dirpath, dirnames, filenames in os.walk(root):
            # avoid deep traversal
            if dirpath.count(os.sep) - root.count(os.sep) > 4:
                dirnames[:] = []
                continue
            for f in filenames:
                if f in ("reads_R1.fastq.gz","reads_R2.fastq.gz","hg19mini.fasta") or f.startswith("hg19mini"):
                    hits.append(os.path.join(dirpath,f))
print("FOUND:", hits[:50])
